// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address nonOwner, uint256 ethAmount) public {
        vm.assume(nonOwner != address(this));
        vm.deal(address(c), ethAmount);
        vm.prank(nonOwner);
        bool ok;
        try c.withdrawAll(nonOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
